import java.util.*;
import java.io.*;

public class Main {
    static class TreeNode {
        long val;
        TreeNode left, right;
        TreeNode(long v) { val = v; }
    }

    // Return {smaller, larger} for the required pair, or an empty array if there is none
    static long[] findPair(TreeNode root, long target) {
        // Write your solution here
        return new long[0];
    }

    static TreeNode buildTree(String[] tokens) {
        if (tokens.length == 0 || tokens[0].equals("null")) return null;
        TreeNode root = new TreeNode(Long.parseLong(tokens[0]));
        ArrayDeque<TreeNode> queue = new ArrayDeque<>();
        queue.add(root);
        int i = 1;
        while (!queue.isEmpty() && i < tokens.length) {
            TreeNode node = queue.poll();
            if (i < tokens.length) {
                if (!tokens[i].equals("null")) { node.left = new TreeNode(Long.parseLong(tokens[i])); queue.add(node.left); }
                i++;
            }
            if (i < tokens.length) {
                if (!tokens[i].equals("null")) { node.right = new TreeNode(Long.parseLong(tokens[i])); queue.add(node.right); }
                i++;
            }
        }
        return root;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first = br.readLine();
        while (first != null && first.trim().isEmpty()) first = br.readLine();
        String second = br.readLine();
        while (second != null && second.trim().isEmpty()) second = br.readLine();
        TreeNode root = buildTree(first.trim().split("\\s+"));
        long target = Long.parseLong(second.trim());
        long[] res = findPair(root, target);
        System.out.println(res.length == 0 ? "-1" : res[0] + " " + res[1]);
    }
}
